import{_ as o,o as c,c as d,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/ROC.md","filePath":"manual-zh/ROC.md","lastUpdated":1785684581000}'),E={name:"manual-zh/ROC.md"};function t(R,e,r,l,n,O){return c(),d("div",null,[...e[0]||(e[0]=[a(`<h3 id="_15-19-roc" tabindex="-1">15.19 ROC <a class="header-anchor" href="#_15-19-roc" aria-label="Permalink to &quot;15.19 ROC&quot;">​</a></h3><pre><code>ROC     var_list BY state_var (state_value)
        /PLOT = { CURVE [(REFERENCE)], NONE }
        /PRINT = [ SE ] [ COORDINATES ]
        /CRITERIA = [ CUTOFF({INCLUDE,EXCLUDE}) ]
          [ TESTPOS ({LARGE,SMALL}) ]
          [ CI (confidence) ]
          [ DISTRIBUTION ({FREE, NEGEXPO }) ]
        /MISSING={EXCLUDE,INCLUDE}
</code></pre><p><code>ROC</code> 命令用于绘制数据集的受试者工作特征（ROC）曲线，并估计曲线下面积。这对于分析某个变量作为自然状态预测因子的有效性很有用。</p><p>必需的 var_list 是预测变量列表。变量 state_var 是其取值代表实际状态的变量，state_value 是该变量中表示阳性状态的值。</p><p>可选的子命令 <code>PLOT</code> 用于确定是否绘制以及怎样绘制 <code>ROC</code> 曲线。关键字 <code>CURVE</code> 表示应绘制 <code>ROC</code> 曲线，可选关键字 <code>REFERENCE</code>（应括在括号内）表示应绘制对角线参考线。如果给定关键字 <code>NONE</code>，则不绘制 <code>ROC</code> 曲线。默认情况下会绘制曲线但不绘制参考线。</p><p>可选的子命令 <code>PRINT</code> 决定应打印哪些额外的表格。有两种额外的表格可用。<code>SE</code> 关键字表示除曲线下面积本身外，还应打印面积的标准误。此外，还会打印原假设“曲线下面积等于 0.5”的 p 值。<code>COORDINATES</code> 关键字表示应打印 <code>ROC</code> 曲线坐标表。</p><p><code>CRITERIA</code> 子命令有四个可选参数：</p><ul><li><code>TESTPOS</code> 参数可以是 <code>LARGE</code> 或 <code>SMALL</code>。默认是 <code>LARGE</code>，表示预测变量中较大的值视为阳性。<code>SMALL</code> 表示较小的值应视为阳性。</li><li><code>CI</code> 参数指定应打印的置信区间。如果未给出 <code>PRINT</code> 子命令中的 <code>SE</code> 关键字，则该参数不起作用。</li><li><code>DISTRIBUTION</code> 参数决定估计曲线下面积时使用的方法。有两种可能，即：<code>FREE</code> 和 <code>NEGEXPO</code>。<code>FREE</code> 方法使用非参数估计，<code>NEGEXPO</code> 方法使用双负指数分布估计。<code>NEGEXPO</code> 方法只应在阳性实际状态的数量等于阴性实际状态的数量时使用。默认是 <code>FREE</code>。</li><li><code>CUTOFF</code> 参数仅为兼容性而设，会被忽略。</li></ul><p><code>MISSING</code> 子命令决定用户缺失值是纳入还是排除在分析之外。默认行为是排除它们。个案按列表方式排除；如果 var_list 中的任意变量或变量 state_var 为缺失值，则整个个案被排除。</p>`,9)])])}const s=o(E,[["render",t]]);export{_ as __pageData,s as default};
